import axios from 'axios';

const EMAIL_SERVICE_URL = 'https://api.emailjs.com/api/v1.0/email/send'; // Replace with your email service API URL
const USER_ID = 'IZIATLqvSb9yQ11-2'; // Replace with your user ID from the email service
const TEMPLATE_ID = 'template_rwz5wyg'; // Replace with your email template ID
const SERVICE_ID = 'service_eob1h3i';

export const sendEmail = (formData) => {
  const { name, email, message } = formData;

  const emailData = {
    service_id: SERVICE_ID, 
    template_id: TEMPLATE_ID,
    user_id: USER_ID,
    template_params: {
      name,
      email,
      message,
    },
  };

  return axios.post(EMAIL_SERVICE_URL, emailData)
    .then(response => {
      if (response.status === 200) {
        return { success: true, message: 'Email sent successfully!' };
      } else {
        throw new Error('Failed to send email.');
      }
    })
    .catch(error => {
      return { success: false, message: error.message };
    });
};