import React, { useState, Suspense } from 'react';
import { sendEmail } from './EmailSender';


// Inline ContactForm komponens lazy load-hoz optimalizálva
const ContactForm = React.lazy(() =>
  Promise.resolve({
    default: ({
      form,
      handleChange,
      handleSubmit,
      captchaValue,
      error,
      submitted
    }) => (
      <form onSubmit={handleSubmit} style={{ width: '100%' }}>
        <div style={{ marginBottom: '0.7rem' }}>
          <input
            type="text"
            name="name"
            placeholder="Your name"
            value={form.name}
            onChange={handleChange}
            style={{
              width: '100%',
              padding: '0.35rem 0.5rem',
              borderRadius: 0,
              border: '1px solid #ccc',
              fontSize: '0.97rem'
            }}
            required
            autoComplete="name"
          />
        </div>
        <div style={{ marginBottom: '0.7rem' }}>
          <input
            type="email"
            name="email"
            placeholder="Your email"
            value={form.email}
            onChange={handleChange}
            style={{
              width: '100%',
              padding: '0.35rem 0.5rem',
              borderRadius: 0,
              border: '1px solid #ccc',
              fontSize: '0.97rem'
            }}
            required
            autoComplete="email"
          />
        </div>
        <div style={{ marginBottom: '0.7rem' }}>
          <textarea
            name="message"
            placeholder="Your message"
            value={form.message}
            onChange={handleChange}
            style={{
              width: '100%',
              padding: '0.35rem 0.5rem',
              borderRadius: 0,
              border: '1px solid #ccc',
              minHeight: 60,
              fontSize: '0.97rem'
            }}
            required
          />
        </div>
        <div style={{ marginBottom: '0.7rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <label htmlFor="captcha" style={{ margin: 0, fontWeight: 500 }}>
            {captchaValue.question} =
          </label>
          <input
            type="text"
            name="captcha"
            id="captcha"
            placeholder="?"
            value={form.captcha}
            onChange={handleChange}
            style={{
              width: 48,
              padding: '0.35rem 0.5rem',
              borderRadius: 0,
              border: '1px solid #ccc',
              fontSize: '0.97rem'
            }}
            required
            autoComplete="off"
          />
        </div>
        {error && <div style={{ color: 'red', marginBottom: '0.7rem' }}>{error}</div>}
        {submitted ? (
          <div style={{ color: 'var(--accent, #388e3c)', fontWeight: 600 }}>Thank you for your message!</div>
        ) : (
          <button
            type="submit"
            style={{
              background: 'var(--accent, #b77b3b)',
              color: '#fff',
              border: 'none',
              borderRadius: 0,
              padding: '0.5rem 1.2rem',
              fontWeight: 600,
              fontSize: '1rem',
              cursor: 'pointer',
              boxShadow: '0 2px 8px 0 rgba(62,39,35,0.10)'
            }}
          >
            Send
          </button>
        )}
      </form>
    )
  })
);

const Contact = () => {
  const [form, setForm] = useState({ name: '', email: '', message: '', captcha: '' });
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState('');
  const [captchaValue, setCaptchaValue] = useState(() => {
    const a = Math.floor(Math.random() * 10) + 1;
    const b = Math.floor(Math.random() * 10) + 1;
    return { question: `${a} + ${b}`, answer: (a + b).toString() };
  });
  const [loading, setLoading] = useState(false); // Új: email küldés állapota

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
    setError('');
  };

  const handleSubmit = async e => {
    e.preventDefault();
    // Email validáció (egyszerű regexp)
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailPattern.test(form.email)) {
      setError('Please enter a valid email address.');
      return;
    }
    if (form.captcha !== captchaValue.answer) {
      setError('Captcha is incorrect.');
      return;
    }
    if (!form.name || !form.email || !form.message) {
      setError('Please fill in all fields.');
      return;
    }
    setLoading(true);
    const { success, message } = await sendEmail(form);
    setLoading(false);
    if (success) {
      setSubmitted(true);
      setForm({ name: '', email: '', message: '', captcha: '' });
      setError('');
    } else {
      setError(message || 'Failed to send email.');
    }
  };

  return (
    <section
      id="contact-section"
      className="contact"
      style={{
        position: 'relative',
        overflow: 'hidden',
        color: 'var(--main-text, #3e2723)',
        borderRadius: '0px',
        marginLeft: '10vw',
        marginRight: '10vw',
        padding: '3rem 2rem',
        display: 'flex',
        alignItems: 'flex-start',
        gap: '3rem',
        minHeight: '340px',
        flexDirection: 'row',
        background: 'transparent'
      }}
      aria-label="Contact section"
    >
      {/* Tartalom */}
      <div
        style={{
          flex: 1,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'flex-start',
          minWidth: 0,
          position: 'relative',
          zIndex: 1
        }}
      >
        <h2 style={{ color: 'var(--accent, #388e3c)', marginBottom: '1.5rem', textAlign: 'left' }}>Contact</h2>
        <img
          src="/images/bbdevelopcontact.jpg"
          alt="Contact illustration"
          style={{
            maxWidth: '320px',
            width: '100%',
            objectFit: 'cover',
            minHeight: '220px',
            marginBottom: '1.5rem'
          }}
          loading="lazy"
          decoding="async"
        />
        
      </div>
      <div
        style={{
          flex: 2,
          fontSize: '1.2rem',
          lineHeight: 1.7,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'flex-start',
          height: '100%',
          minWidth: 0,
          position: 'relative',
          zIndex: 1
        }}
      >
        <div style={{ height: '1.5rem' }} aria-hidden="true" />
        <h5
          style={{
            color: '#b77b3b',
            marginBottom: '1rem',
            fontSize: '1.25rem',
            fontWeight: 700,
            marginTop: 0
          }}
        >
          Send message
        </h5>
        <Suspense fallback={<div style={{ textAlign: 'center' }}>Loading form...</div>}>
          <ContactForm
            form={form}
            handleChange={handleChange}
            handleSubmit={handleSubmit}
            captchaValue={captchaValue}
            error={error}
            submitted={submitted}
          />
          {loading && (
            <div style={{ color: '#b77b3b', marginTop: '1rem', fontWeight: 500 }}>
              Sending message...
            </div>
          )}
        </Suspense>
      </div>
      <style>
        {`
          @media (max-width: 900px) {
            .contact {
              flex-direction: column !important;
              gap: 2rem !important;
              padding: 2rem 0.5rem !important;
            }
            .contact svg {
              display: none !important;
            }
          }
        `}
      </style>
    </section>
  );
};

export default Contact;
